require dirname(__DIR__).'/automation-engine.php';
$u=require_login();$cid=(int)$u['company_id'];$pdo=db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method!=='GET')verify_csrf();$action=(string)($_GET['action']??'logs');
try{
 switch($action){
  case 'logs':require_cap_v10('communications.read');$limit=min(300,max(20,(int)($_GET['limit']??100)));$st=$pdo->prepare('SELECT c.*,u.name user_name FROM communication_logs c LEFT JOIN users u ON u.id=c.user_id WHERE c.company_id=? ORDER BY c.created_at DESC LIMIT '.$limit);$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
