    if($channel==='email'){$cfg=integration_settings($cid,'email');if(!$cfg['enabled'])json_response(['ok'=>false,'error'=>'email_not_configured'],422);[$ok,$msg]=smtp_send($cfg['settings'],$to,$subject,nl2br(e($body)));log_communication($cid,(int)$u['id'],'email',$to,$subject,$body,$ok?'sent':'failed',$cfg['provider'],$ok?'':$msg);if($entity&&$eid)v10_timeline($entity,$eid,'email',$subject,$body,'communication',null,(int)$u['id'],['status'=>$ok?'sent':'failed','recipient'=>$to]);json_response(['ok'=>$ok,'message'=>$msg],$ok?200:502);}
