    json_response(['ok'=>false,'error'=>'bad_channel'],422);
  case 'templates':require_cap_v10('communications.read');$st=$pdo->prepare('SELECT * FROM v10_message_templates WHERE company_id=? ORDER BY channel,name');$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
