  case 'delete_template':require_cap_v10('communications.write');$b=body_json();$pdo->prepare('DELETE FROM v10_message_templates WHERE id=? AND company_id=?')->execute([(int)req($b,'id',0),$cid]);json_response(['ok'=>true]);
