  case 'calls':require_cap_v10('communications.read');$st=$pdo->prepare('SELECT c.*,cu.name customer_name,ct.name contact_name,u.name user_name FROM v10_call_logs c LEFT JOIN customers cu ON cu.id=c.customer_id LEFT JOIN contacts ct ON ct.id=c.contact_id LEFT JOIN users u ON u.id=c.user_id WHERE c.company_id=? ORDER BY c.started_at DESC LIMIT 300');$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
