;if($customer)v10_timeline('customers',$customer,'call','Phone call',(string)req($b,'notes',''),'call',$id,(int)$u['id'],['phone'=>$phone,'status'=>$status]);json_response(['ok'=>true,'id'=>$id,'status'=>$status,'tel'=>'tel:'.$phone]);
  default:json_response(['ok'=>false,'error'=>'unknown_action'],404);
 }
